import pandas as pd
from datetime import timedelta

def run(inputs: dict) -> dict:
    df = inputs["app_events"].copy()

    df = df.sort_values(["user_id", "event_ts", "event_id"], kind="mergesort")

    results = []

    for user_id, grp in df.groupby("user_id", sort=False):
        session_num = 0
        cur = None  # dict: session_start, last_activity_ts, event_count, heartbeat_count

        def finalize(cur):
            results.append({
                "user_id": user_id,
                "session_num": cur["session_num"],
                "session_start": cur["session_start"],
                "session_end": cur["last_activity_ts"],
                "event_count": cur["event_count"],
                "heartbeat_count": cur["heartbeat_count"],
            })

        for row in grp.itertuples(index=False):
            ts = row.event_ts
            etype = row.event_type

            if etype in ("view", "click", "logout"):
                start_new = False
                if cur is None:
                    start_new = True
                else:
                    delta = ts - cur["last_activity_ts"]
                    if delta > timedelta(minutes=30):
                        start_new = True

                if start_new:
                    if cur is not None:
                        finalize(cur)
                    session_num += 1
                    cur = {
                        "session_num": session_num,
                        "session_start": ts,
                        "last_activity_ts": ts,
                        "event_count": 1,
                        "heartbeat_count": 0,
                    }
                else:
                    cur["last_activity_ts"] = ts
                    cur["event_count"] += 1

                if etype == "logout":
                    finalize(cur)
                    cur = None

            else:  # heartbeat
                if cur is not None:
                    delta = ts - cur["last_activity_ts"]
                    if delta <= timedelta(minutes=30):
                        cur["event_count"] += 1
                        cur["heartbeat_count"] += 1
                    # else: dropped
                # else: dropped

        if cur is not None:
            finalize(cur)

    if results:
        out = pd.DataFrame(results, columns=[
            "user_id", "session_num", "session_start", "session_end",
            "event_count", "heartbeat_count"
        ])
    else:
        out = pd.DataFrame(columns=[
            "user_id", "session_num", "session_start", "session_end",
            "event_count", "heartbeat_count"
        ])

    return {"user_sessions": out}
